(()=>{const en=document.documentElement.lang==='en';const currentForm=document.querySelector('#cerere');currentForm.addEventListener('invalid',event=>{const field=event.target;if(!(field instanceof HTMLInputElement||field instanceof HTMLTextAreaElement))return;const validity=field.validity;if(validity.valueMissing)field.setCustomValidity(field.type==='checkbox'?(en?'Please confirm that you have read the Privacy Policy.':'Confirmă că ai citit Politica de Confidențialitate.'):(en?'Please complete this required field.':'Completează acest câmp obligatoriu.'));else if(validity.typeMismatch&&field.type==='email')field.setCustomValidity(en?'Please enter a valid email address.':'Introdu o adresă de e-mail validă.');else if(validity.tooShort)field.setCustomValidity(en?'Please enter at least '+field.minLength+' characters.':'Introdu cel puțin '+field.minLength+' caractere.');},true);document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||form.id!=='cerere')return;for(const field of form.querySelectorAll('input[required]:not([type=checkbox]),textarea[required]')){if(!field.value.trim()){field.setCustomValidity(en?'Please complete this required field.':'Completează acest câmp obligatoriu.');event.preventDefault();event.stopImmediatePropagation();field.reportValidity();return}field.value=field.value.trim()}if(!form.checkValidity()){event.preventDefault();event.stopImmediatePropagation();form.reportValidity()}},true);currentForm.addEventListener('input',event=>{if(event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement)event.target.setCustomValidity('')});currentForm.addEventListener('change',event=>{if(event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement)event.target.setCustomValidity('')});})();
